\documentclass{article}
% Portrait A0
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Custom Dark Mode Theme ──
\definecolor{primary}{HTML}{3B82F6}     % Bright Blue
\definecolor{secondary}{HTML}{10B981}   % Bright Green (Gains)
\definecolor{accent}{HTML}{EF4444}      % Bright Red (Losses)
\definecolor{bgposter}{HTML}{0B1120}    % Deep Navy/Charcoal background
\definecolor{cardbg}{HTML}{111827}      % Dark gray cards
\definecolor{cardtitlebg}{HTML}{1F2937} % Lighter dark gray title bars
\definecolor{textmain}{HTML}{F9FAFB}    % Off-white body text
\definecolor{textgray}{HTML}{9CA3AF}    % Gray secondary text
\definecolor{stathighlight}{HTML}{1E293B} % Stat background

\pagecolor{bgposter}
\color{textmain}

\setlist[itemize]{leftmargin=24pt, itemsep=10pt, parsep=2pt, topsep=2pt,
  label={\color{primary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=10pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles (Dark Mode) ──
\tcbset{
  darkcard/.style={
    enhanced, arc=8pt, boxrule=0pt, colback=cardbg, colupper=textmain,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\sffamily\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardtitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3, color=black},
  },
  greencard/.style={
    enhanced, arc=8pt, boxrule=0pt, colback=cardbg, colupper=textmain,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\sffamily\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardtitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3, color=black},
  },
  redcard/.style={
    enhanced, arc=8pt, boxrule=0pt, colback=cardbg, colupper=textmain,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\sffamily\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardtitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3, color=black},
  },
  highlightcard/.style={
    enhanced, arc=8pt, boxrule=0pt, colback=primary!20!black, colupper=textmain,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\sffamily\bfseries\color{textmain},
    coltitle=textmain, colbacktitle=primary,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.5, color=black},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=6mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=bgposter, colframe=bgposter, colupper=textmain,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=12pt, bottom=8pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{72}{86}\selectfont\sffamily\bfseries PYPL Programming Language Popularity Index}\\[16pt]
  {\fontsize{36}{44}\selectfont\color{primary} A Data-Driven Snapshot of Global Tutorial Searches — April 2026}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{textgray} 30 Languages Tracked | Worldwide Trends}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=center,
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{72}{86}\selectfont\bfseries\ttfamily\color{textmain} 36.21\%}\\[8pt]
      {\fontsize{32}{40}\selectfont\color{primary} PYTHON SHARE (\#1)}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textgray} +5.7\% YoY (Dominant Lead)}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{72}{86}\selectfont\bfseries\ttfamily\color{secondary} 13.21\%}\\[8pt]
      {\fontsize{32}{40}\selectfont\color{secondary} C/C++ SHARE (\#2)}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textgray} \textbf{+6.2\% YoY} (Largest Gain)}\vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
      {\fontsize{72}{86}\selectfont\bfseries\ttfamily\color{accent} 10.01\%}\\[8pt]
      {\fontsize{32}{40}\selectfont\color{accent} JAVA SHARE (\#3)}\\[6pt]
      {\fontsize{26}{32}\selectfont\color{textgray} \textbf{-5.4\% YoY} (Steep Decline)}\vspace{12pt}%
    }}
  \end{minipage}
}

% ══ CONTENT CARDS ══

% ROW BAND A: row5 to row14

\posterbox[darkcard, title={Top 10 Languages by Search Share}
]{name=rankings, column=1, span=2, between=row5 and row13}{
  \vspace{10pt}
  \renewcommand{\arraystretch}{1.6}
  \fontsize{32}{42}\selectfont\ttfamily
  \centering
  \begin{tabular}{rlp{6cm}rr}
    \rowcolor{primary!15}
    \textbf{\#}&\textbf{Language}&\textbf{Share}&\textbf{1-Year Trend}&\textbf{Status} \\
    \rowcolor{bgposter}
    1 & Python      & 36.21\% & \color{secondary}+5.7\% & $\uparrow\uparrow$ \\
    \rowcolor{cardbg}
    2 & C/C++       & 13.21\% & \color{secondary}\textbf{+6.2\%} & $\uparrow\uparrow\uparrow$ \\
    \rowcolor{bgposter}
    3 & Java        & 10.01\% & \color{accent}-5.4\% & $\downarrow\downarrow$ \\
    \rowcolor{cardbg}
    4 & R           & 6.17\%  & \color{secondary}+1.6\% & $\uparrow$ \\
    \rowcolor{bgposter}
    5 & JavaScript  & 5.07\%  & \color{accent}-3.0\% & $\downarrow$ \\
    \rowcolor{cardbg}
    6 & Swift       & 3.15\%  & \color{secondary}+0.8\% & $\uparrow$ \\
    \rowcolor{bgposter}
    7 & C\#         & 3.00\%  & \color{accent}-3.0\% & $\downarrow$ \\
    \rowcolor{cardbg}
    8 & Rust        & 2.98\%  & \color{textgray}-0.1\% & $\rightarrow$ \\
    \rowcolor{bgposter}
    9 & PHP         & 2.96\%  & \color{accent}-0.7\% & $\downarrow$ \\
    \rowcolor{cardbg}
    10 & Objective-C & 2.57\%  & \color{secondary}+0.1\% & $\rightarrow$ \\
  \end{tabular}

  \vspace{30pt}\sffamily
  \colorbox{primary!20}{\parbox{0.8\linewidth}{
    \centering \textbf{Python} accounts for >1/3 of searches, triple its closest competitor.
  }}
}

\posterbox[darkcard, title={Biggest Gainers \& Losers}
]{name=movers, column=3, between=row5 and row13}{
  \fontsize{32}{42}\selectfont\sffamily
  \textbf{Surging Adoption (\color{secondary}Gainers\color{textmain}):}
  \begin{itemize}[label={\color{secondary}$\blacktriangle$}]
    \item \textbf{C/C++ (\color{secondary}+6.2\%\color{textmain}):} The breakout story of 2026. Largest single-year jump.
    \item \textbf{Python (\color{secondary}+5.7\%\color{textmain}):} Strong growth cements \#1 dominance.
    \item \textbf{R (\color{secondary}+1.6\%\color{textmain}):} Data science demand continues to rise.
  \end{itemize}

  \vspace{30pt}
  \textbf{Losing Ground (\color{accent}Losers\color{textmain}):}
  \begin{itemize}[label={\color{accent}$\blacktriangledown$}]
    \item \textbf{Java (\color{accent}-5.4\%\color{textmain}):} Massive continuous drop. Long slide persists.
    \item \textbf{JavaScript (\color{accent}-3.0\%\color{textmain}):} Under significant pressure.
    \item \textbf{C\# (\color{accent}-3.0\%\color{textmain}):} Dropping alongside JS.
  \end{itemize}
}

% ROW BAND B: row13 to row20

\posterbox[greencard, title={5-Year Trend Spotlight}
]{name=longterm, column=1, between=row13 and row20}{
  \fontsize{30}{40}\selectfont\sffamily
  \begin{itemize}
    \item \colorbox{secondary!20}{\parbox{0.9\linewidth}{\textbf{C/C++ (+7.0\%):} Biggest 5-year cumulative growth of any language.}}
    \item \vspace{8pt} \colorbox{accent!20}{\parbox{0.9\linewidth}{\textbf{Java (-7.0\%):} Steepest 5-year decline tracked globally.}}
    \item \vspace{8pt} \textbf{Python:} Solidified its multi-year reign as \#1.
  \end{itemize}
  \vspace{20pt}
  \color{textgray}\textit{Data indicates a long-term shift toward systems languages and Python at the expense of enterprise JVM mainstays.}
}

\posterbox[darkcard, title={Languages to Watch}
]{name=emerging, column=2, between=row13 and row20}{
  \fontsize{30}{40}\selectfont\sffamily
  \begin{itemize}
    \item \textbf{Ada (\color{secondary}+1.1\%\color{textmain}):} Strong growth in safety-critical domains.
    \item \textbf{Julia (\color{secondary}+0.4\%\color{textmain}):} Steady rise in scientific computing.
    \item \textbf{Rust (\color{textgray}-0.1\%\color{textmain}):} Steady at 2.98\%, holding position but growth is flat.
    \item \textbf{Go (\color{accent}-1.3\%\color{textmain}):} Notable decline despite cloud-native popularity.
    \item \textbf{Kotlin (\color{accent}-0.9\%\color{textmain}):} Declining despite official Android backing.
  \end{itemize}
}

\posterbox[highlightcard, title={Key Takeaways}
]{name=takeaways, column=3, between=row13 and row20}{
  \fontsize{30}{40}\selectfont\sffamily
  \begin{itemize}[label={\color{white}$\blacktriangleright$}]
    \item \textbf{Python reigns:} Unchallenged at 36.21\% and expanding.
    \item \textbf{C/C++ surge:} Breakout momentum year-over-year.
    \item \textbf{Java slide:} Enterprise mainstay continues dramatic descent.
    \item \textbf{Methodology:} PYPL measures tutorial search interest (learning intent), making it a leading indicator of language momentum.
  \end{itemize}
}

\end{tcbposter}
\end{document}
EOF

